// Renderiza um icone de marca a partir do seu nome (ex: 'brand:netflix'). Retorna null se nao for um icone de marca conhecido.
export function BrandIconRenderer({ iconName, className, style }: { iconName: string; className?: string; style?: React.CSSProperties }): React.ReactElement | null {
  if (!iconName || !iconName.startsWith('brand:')) return null;
  const slug = iconName.slice('brand:'.length);
  const d = BRAND_PATHS[slug];
  if (!d) return null;
  return (
    <svg viewBox="0 0 24 24" className={className} style={style} fill="currentColor" xmlns="http://www.w3.org/2000/svg">
      <path d={d} />
    </svg>
  );
}
